class Solution {
  public int minimumSubarrayLength(int[] nums, int k) {
    int[] bits = new int[31];
    int left = 0, answer = Integer.MAX_VALUE;
    for (int right = 0; right < nums.length; right++) {
      add(bits, nums[right], 1);
      while (left <= right && value(bits) >= k) {
        answer = Math.min(answer, right - left + 1);
        add(bits, nums[left++], -1);
      }
    }
    return answer == Integer.MAX_VALUE ? -1 : answer;
  }

  private void add(int[] bits, int value, int delta) {
    for (int b = 0; b < 31; b++) if ((value & (1 << b)) != 0) bits[b] += delta;
  }

  private int value(int[] bits) {
    int result = 0;
    for (int b = 0; b < 31; b++) if (bits[b] > 0) result |= 1 << b;
    return result;
  }
}
